<div class="shell"><aside><b>ABLESTACK</b><p>대시보드</p><p>컴퓨트　⌄</p><p>　가상머신</p><p>스토리지　⌄</p><div class="selected">공유 파일 시스템</div><p>네트워크</p><p>이미지</p></aside><div class="workspace"><header><span>☰　기본 보기</span><span>AC　admin cloud</span></header>
<a-card class="breadcrumb-card"><a-row align="middle"><a-col :span="18"><Breadcrumb :resource="view==='list'?{}:{name:'sharedfs-preserve-design'}"><template #end><a-button size="small" shape="round"><ReloadOutlined/>업데이트</a-button></template></Breadcrumb></a-col><a-col :span="6" class="right"><a-dropdown v-if="view!=='list'"><a-button>작업 <DownOutlined/></a-button><template #overlay><a-menu><a-menu-item @click="open('preserve')">공유 파일 시스템 제거</a-menu-item></a-menu></template></a-dropdown></a-col></a-row></a-card>
<main><template v-if="view==='list'"><div class="list-toolbar"><a-space><a-button type="primary"><PlusOutlined/>공유 파일 시스템 생성</a-button><a-button @click="open('preserve')"><DeleteOutlined/>제거</a-button><a-button><ReloadOutlined/>업데이트</a-button></a-space><a-input-search placeholder="이름 검색" style="width:220px"/></div><a-table size="small" :columns="listColumns" :data-source="listRows" row-key="id" :pagination="false"><template #bodyCell="{column,record}"><a v-if="column.key==='name'" @click="view='details'">{{record.name}}</a><a-tag v-else-if="column.key==='state'" color="green">사용 가능</a-tag></template></a-table></template>
<ResourceLayout v-else><template #left><a-card class="info"><FileTextOutlined class="icon"/><h3>sharedfs-preserve-design</h3><a-badge status="success" text="사용 가능"/><dl><dt>주 IP</dt><dd>10.10.13.187 (예시)</dd><dt>볼륨</dt><dd>ROOT 1 · DATA 4 (예시)</dd><dt>DATA 합계</dt><dd>40 GiB · SPARSE</dd><dt>계정</dt><dd>admin</dd><dt>Zone</dt><dd>13-Zone</dd></dl></a-card></template>
<template #right><a-card class="tab-card"><a-tabs v-model:activeKey="view" tab-position="left"><a-tab-pane key="details" tab="상세"><a-list size="small" :data-source="details"><template #renderItem="{item}"><a-list-item><div class="detail"><strong>{{item[0]}}</strong><span>{{item[1]}}</span></div></a-list-item></template></a-list></a-tab-pane><a-tab-pane key="capacity" tab="용량·볼륨"><a-space class="spaced"><a-button type="primary">볼륨 연결</a-button><a-button><ReloadOutlined/>업데이트</a-button></a-space><a-table :columns="volumeColumns" :data-source="volumes" row-key="id" :pagination="false" :scroll="{x:780}"/></a-tab-pane><a-tab-pane key="directory" tab="공유 디렉터리"/><a-tab-pane key="nfs" tab="NFS"/><a-tab-pane key="smb" tab="SMB"/><a-tab-pane key="iscsi" tab="iSCSI"/><a-tab-pane key="nvmeof" tab="NVMe-oF"/><a-tab-pane key="runtime" tab="런타임"/><a-tab-pane key="boot" tab="부팅 복구"/><a-tab-pane key="network" tab="네트워크"/><a-tab-pane key="operations" tab="작업 내역"><a-space class="toolbar"><a-button><ReloadOutlined/>업데이트</a-button></a-space><a-table :columns="opColumns" :data-source="operations" row-key="id" :pagination="false"><template #bodyCell="{column}"><a-button v-if="column.key==='detail'" size="small" @click="open('failed')">상세</a-button></template></a-table></a-tab-pane></a-tabs></a-card></template></ResourceLayout></main></div></div>
<MoldDialog v-if="dialog" :visible="true" :title="failed?'제거 작업 진단':'공유 파일 시스템 제거'" size="xl" @cancel="dialog=false">
<template v-if="failed"><a-alert type="warning" show-icon message="분리 확인 실패 · 파괴적 후속 작업 중단 (설계 예시)" description="이미 분리된 DATA는 보존됩니다. VM·ROOT 제거와 선택 DATA 삭제는 진행하지 않았습니다. 같은 계획의 상태를 확인한 후 재개하세요."/>
<a-descriptions bordered :column="2" size="small" class="spaced"><a-descriptions-item label="작업 식별자">계획 UUID (예시)</a-descriptions-item><a-descriptions-item label="현재 단계">DETACHING_DATA</a-descriptions-item><a-descriptions-item label="최초 실패">DATA_DETACH_UNCONFIRMED</a-descriptions-item><a-descriptions-item label="실패 볼륨">data-smb · vol-smb</a-descriptions-item><a-descriptions-item label="가상머신">정지 확인 완료 · ROOT 보존 중</a-descriptions-item><a-descriptions-item label="삭제 실행">0개 · 완료로 표시하지 않음</a-descriptions-item></a-descriptions>
<a-table class="spaced" size="small" :columns="resultColumns" :data-source="results" row-key="id" :pagination="false"/>
<p class="hint">재개는 같은 작업·같은 승인 볼륨으로만 수행합니다. 응답 유실은 삭제 실패/성공으로 추정하지 않습니다. 설정·관계와 최초 오류는 작업 완료 전까지 보존합니다.</p></template>
<template v-else><a-alert type="info" show-icon message="데이터 볼륨을 보존합니다." description="기본 DATA와 추가 파일·블록 DATA는 기본 보존합니다. 영구 제거 시 ROOT만 삭제합니다. 서비스 제거는 데이터 백업을 뜻하지 않습니다."/>
<a-form layout="vertical" class="spaced"><a-form-item label="제거 대상"><a-input value="sharedfs-preserve-design" disabled/></a-form-item><a-form-item label="데이터 볼륨 처리"><a-radio-group v-model:value="policy"><a-radio value="PRESERVE">모든 DATA 보존 · 권장</a-radio><a-radio value="DELETE_SELECTED">선택한 DATA만 삭제</a-radio></a-radio-group></a-form-item>
<a-form-item label="제거 방식"><a-switch v-model:checked="expunge"/><span class="switch-label">즉시 영구 제거</span><p class="hint">{{expunge?'DATA 분리 검증 후 VM·ROOT를 제거합니다. 선택한 DATA만 삭제합니다.':'우선 파기 상태로 전환합니다. 복구 유예 동안 DATA는 연결된 채 보존됩니다. 이후 영구 제거에도 승인한 계획을 사용합니다.'}}</p></a-form-item>
</a-form>
<a-alert v-if="policy==='DELETE_SELECTED'" type="error" show-icon message="선택한 DATA의 데이터가 손실됩니다." description="공유·외부 참조·삭제 보호가 있는 볼륨은 삭제할 수 없습니다. 선택하지 않은 DATA는 보존합니다."/>
<div class="table-header"><strong>실행 전 영향 목록</strong><span class="hint">ROOT 1 · DATA {{volumes.length}} · 선택 삭제 {{selected.length}}개 (예시)</span></div>
<a-table size="small" :columns="impactColumns" :data-source="impactRows" row-key="id" :pagination="false" :scroll="{x:900}"><template #bodyCell="{column,record}"><template v-if="column.key==='action'"><a-tag v-if="record.kind==='ROOT'">VM 영구 제거 시 삭제</a-tag><a-checkbox v-else-if="policy==='DELETE_SELECTED'" :checked="selected.includes(record.id)" :disabled="!record.deletable" @change="choose(record.id,$event.target.checked)">이 DATA 삭제</a-checkbox><a-tag v-else color="blue">보존 후 분리</a-tag></template><template v-else-if="column.key==='protection'"><a-tag v-if="!record.deletable&&record.kind!=='ROOT'" color="orange">{{record.protection}}</a-tag><span v-else>{{record.protection}}</span></template></template></a-table>
<a-alert class="spaced" type="warning" show-icon message="서비스 중단이 필요합니다." description="현재 연결과 실행 중인 구성·포맷·런타임 작업을 점검합니다. 정상 정지 또는 분리 확인에 실패하면 VM·ROOT·DATA 삭제를 진행하지 않습니다."/>
<a-checkbox class="spaced" v-model:checked="stopConfirmed">이 서비스의 클라이언트 I/O를 중단하고 정상 정지하는 것을 확인했습니다.</a-checkbox>
<a-form layout="vertical" class="spaced"><a-form-item label="공유 파일 시스템 이름 확인"><a-input v-model:value="confirmName" placeholder="sharedfs-preserve-design"/></a-form-item><a-checkbox v-if="policy==='DELETE_SELECTED'" v-model:checked="lossConfirmed">선택한 {{selected.length}}개 DATA의 데이터 손실을 확인했습니다.</a-checkbox></a-form>
<p class="hint">목록은 DB·실제 연결 볼륨 UUID의 합집합으로 생성하며 권한·참조·기존 보호를 서버가 다시 확인합니다. 갱신 후 대상이 바뀌면 재확인해야 합니다.</p></template>
<template #footer><a-button @click="dialog=false">{{failed?'닫기':'취소'}}</a-button><a-button v-if="failed" type="primary" @click="notice=true">상태 확인 후 같은 계획 재개</a-button><a-button v-else type="primary" :disabled="!canSubmit" @click="notice=true">{{expunge?'계획 확인 후 영구 제거':'계획 확인 후 파기'}}</a-button></template>
<a-alert v-if="notice" class="spaced" type="info" message="목업입니다. 서버 요청이나 실제 삭제는 실행하지 않습니다."/></MoldDialog>
</div></a-config-provider>
</template>
<script>
import koKR from 'ant-design-vue/es/locale/ko_KR'
import Breadcrumb from '@/components/widgets/Breadcrumb.vue'
import ResourceLayout from '@/layouts/ResourceLayout.vue'
import MoldDialog from '@/components/view/MoldDialog.vue'
import {ReloadOutlined,PlusOutlined,DownOutlined,FileTextOutlined,DeleteOutlined} from '@ant-design/icons-vue'
const q=new URLSearchParams(location.search)
export default {components:{Breadcrumb,ResourceLayout,MoldDialog,ReloadOutlined,PlusOutlined,DownOutlined,FileTextOutlined,DeleteOutlined},
data(){return {locale:koKR,view:q.get('view')||'details',dark:q.get('theme')==='dark',dialog:!!q.get('dialog'),failed:q.get('dialog')==='failed',policy:q.get('dialog')==='selected'?'DELETE_SELECTED':'PRESERVE',selected:q.get('dialog')==='selected'?['block-iscsi']:[],expunge:true,confirmName:'',stopConfirmed:false,lossConfirmed:false,notice:false,
volumes:[{id:'base',name:'기본 DATA',kind:'DATA',purpose:'NFS · SMB / 2공유',size:'10 GiB · XFS',ownership:'이 서비스 생성',protection:'없음',deletable:true},{id:'smb',name:'추가 파일 DATA',kind:'DATA',purpose:'SMB / 1공유',size:'10 GiB · EXT4',ownership:'기존 볼륨 연결',protection:'삭제 보호',deletable:false},{id:'block-iscsi',name:'iSCSI DATA',kind:'DATA',purpose:'iSCSI / LUN 1',size:'10 GiB · RAW',ownership:'이 서비스 생성',protection:'없음',deletable:true},{id:'block-nvme',name:'NVMe DATA',kind:'DATA',purpose:'NVMe-oF / NS 1',size:'10 GiB · RAW',ownership:'기존 볼륨 연결',protection:'공유 볼륨 · 외부 연결',deletable:false}],
listColumns:[{title:'이름',dataIndex:'name',key:'name'},{title:'상태',key:'state'},{title:'스토리지',dataIndex:'capacity'},{title:'계정',dataIndex:'account'},{title:'Zone',dataIndex:'zone'}],listRows:[{id:'design',name:'sharedfs-preserve-design',capacity:'40 GiB · DATA 4',account:'admin',zone:'13-Zone'}],
impactColumns:[{title:'볼륨',dataIndex:'name',width:145},{title:'용도 / 참조',dataIndex:'purpose',width:150},{title:'크기 / 형식',dataIndex:'size',width:135},{title:'출처',dataIndex:'ownership',width:130},{title:'보호 / 공유',key:'protection',width:155},{title:'계획',key:'action',width:160}],
volumeColumns:[{title:'볼륨',dataIndex:'name'},{title:'용도',dataIndex:'purpose'},{title:'크기',dataIndex:'size'},{title:'출처',dataIndex:'ownership'}],
opColumns:[{title:'생성일',dataIndex:'created'},{title:'유형',dataIndex:'type'},{title:'현재 단계',dataIndex:'phase'},{title:'상태',dataIndex:'state'},{title:'진단',key:'detail'}],operations:[{id:'plan',created:'예시 2026-11-05 14:00',type:'서비스 제거',phase:'DATA 분리',state:'확인 필요 · 재개 가능'}],
resultColumns:[{title:'볼륨',dataIndex:'name'},{title:'승인 정책',dataIndex:'policy'},{title:'실제 관측',dataIndex:'state'}],results:[{id:'base',name:'기본 DATA',policy:'보존',state:'분리 확인 완료 · Ready'},{id:'smb',name:'추가 파일 DATA',policy:'보존',state:'분리 확인 불가 · 원래 연결 정보 보존'},{id:'root',name:'ROOT',policy:'VM 제거 시 삭제',state:'미실행 · 보존 중'}]}},
watch:{view(v){this.$router.push(v==='list'?'/sharedfs':'/sharedfs/design-preserve')},dark:{immediate:true,handler(v){document.body.classList.toggle('dark-mode',v)}},policy(v){if(v==='PRESERVE')this.selected=[];this.lossConfirmed=false}},
computed:{impactRows(){return [{id:'root',name:'ROOT',kind:'ROOT',purpose:'SystemVM OS',size:'5 GiB · SPARSE',ownership:'전용 VM',protection:'OS 디스크'},...this.volumes]},details(){return [['이름','sharedfs-preserve-design'],['상태','Ready'],['주 IP','10.10.13.187 (예시)'],['프로토콜','NFS · SMB · iSCSI · NVMe-oF'],['프로비저닝','SPARSE'],['계정','admin'],['Zone','13-Zone']]},canSubmit(){return this.confirmName==='sharedfs-preserve-design'&&this.stopConfirmed&&(this.policy==='PRESERVE'||this.selected.length>0&&this.lossConfirmed)}},
methods:{open(kind){this.failed=kind==='failed';this.policy=kind==='selected'?'DELETE_SELECTED':'PRESERVE';this.selected=kind==='selected'?['block-iscsi']:[];this.dialog=true;this.notice=false},choose(id,on){this.selected=on?[...new Set([...this.selected,id])]:this.selected.filter(v=>v!==id)}}}
</script>
<style>
